<?php $q=trim($_GET['q']??'');$type=$_GET['type']??'';$work=$_GET['work']??'';$jobs=array_values(array_filter(jobs_for_viewer(),function($j)use($q,$type,$work){$hay=strtolower($j['title'].' '.$j['company'].' '.$j['location'].' '.$j['category'].' '.$j['description']);return (!$q||str_contains($hay,strtolower($q)))&&(!$type||$j['type']===$type)&&(!$work||$j['workplace']===$work);})); ?><div class="page-container"><div class="page-heading"><div><span class="eyebrow eyebrow-dark">FIND YOUR NEXT MOVE</span><h1>Find work that <span>fits.</span></h1><p class="muted">Explore opportunities from teams looking for people like you.</p></div><span class="result-count"><strong><?=count($jobs)?></strong> opportunities</span></div><form class="search-panel" method="get"><input type="hidden" name="page" value="jobs"><label class="search-field"><span>⌕</span><input name="q" value="<?=e($q)?>" placeholder="Job title, skill, or company"></label><label class="filter-field"><span>◷</span><select name="type"><option value="">All employment types</option><?php foreach(['Full Time','Part Time','Internship','Contract','Casual'] as $t):?><option value="<?=e($t)?>" <?=$type===$t?'selected':''?>><?=e($t)?></option><?php endforeach;?></select></label><label class="filter-field"><span>⌖</span><select name="work"><option value="">All workplace types</option><?php foreach(['Remote','Hybrid','On-site'] as $w):?><option value="<?=e($w)?>" <?=$work===$w?'selected':''?>><?=e($w)?></option><?php endforeach;?></select></label><button class="btn btn-dark" type="submit">Search</button></form><div class="job-page-layout"><aside class="job-sidebar"><div class="sidebar-heading">Explore by category</div><?php foreach(['All opportunities','Technology','Design','Data','Marketing','Customer Support'] as $cat):?><a class="category-link <?=$q===$cat?'selected':''?>" href="<?=url('jobs',['q'=>$cat==='All opportunities'?'':$cat])?>"><span><?=e($cat)?></span><span>↗</span></a><?php endforeach;?><div class="sidebar-tip"><span>✦</span><strong>A little tip</strong><p>Use filters to narrow the list and focus on roles that match your goals.</p></div></aside><div class="job-results"><div class="results-heading"><span>Showing <strong><?=count($jobs)?></strong> roles</span><span class="muted small">Recently added first</span></div><?php if($jobs):?><div class="job-list"><?php foreach($jobs as $j)render_job_card($j);?></div><?php else:?><div class="empty-state"><span>⌕</span><h3>No roles found just yet</h3><p>Try a different keyword or clear one of your filters.</p><a class="btn btn-outline-dark" href="<?=url('jobs')?>">Clear filters</a></div><?php endif;?></div></div></div>